mapper.sql:
FROM ph_inv_stocktake t
WHERE t.tenant_id = #{scope.tenantId} AND t.store_id = #{scope.storeId} AND t.deleted = b'0'
AND t.warehouse_id = #{q.warehouseId}
AND t.status = #{q.status}

mapper.update:
UPDATE ph_inv_stocktake
SET status = #{to}, updater = #{operator}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id} AND tenant_id = #{scope.tenantId} AND store_id = #{scope.storeId}
  AND deleted = b'0' AND status = #{from}

mapper.select:
SELECT COUNT(*) FROM ph_inv_stocktake_line
WHERE stocktake_id = #{id} AND tenant_id = #{scope.tenantId}
  AND deleted = b'0' AND real_qty IS NOT NULL

SELECT id, status, store_id FROM ph_warehouse
WHERE id = #{id} AND tenant_id = #{scope.tenantId} AND store_id = #{scope.storeId}
  AND deleted = b'0' FOR UPDATE
